document.querySelectorAll('[data-lab="L05-I1"]').forEach(root=>{if(root.dataset.ready)return;root.dataset.ready='1';const mode=root.querySelector('[data-mode]'),s=root.querySelector('[data-coordinate-value]'),en=root.dataset.lang==='en';const models={bond:{lo:.90,hi:1.12,step:.001,start:1.012,label:'r / Å',f:x=>529.581*(x-1.012)**2},angle:{lo:95,hi:130,step:.01,start:113.24,label:'θ / °',f:x=>37.95*((x-113.24)*Math.PI/180)**2},torsion:{lo:-180,hi:180,step:1,start:60,label:'φ / °',f:x=>.3011*(1+Math.cos(3*x*Math.PI/180))}};function draw(){const a=models[mode.value],x=Number(s.value),y=a.f(x),pts=Array.from({length:401},(_,i)=>{const q=a.lo+(a.hi-a.lo)*i/400;return[q,a.f(q)]}),top=Math.max(...pts.map(p=>p[1]))*1.08,map=(q,e)=>[75+775*(q-a.lo)/(a.hi-a.lo),285-240*e/top];root.querySelector('[data-curve]').setAttribute('points',pts.map(p=>map(...p).join(',')).join(' '));const [cx,cy]=map(x,y);root.querySelector('[data-selected]').setAttribute('cx',cx);root.querySelector('[data-selected]').setAttribute('cy',cy);root.querySelector('[data-x-label]').textContent=a.label;root.querySelector('[data-coordinate]').textContent=a.label;root.querySelector('[data-number]').textContent=x.toFixed(mode.value==='bond'?3:2);root.querySelector('[data-xmin]').textContent=a.lo;root.querySelector('[data-xmax]').textContent=a.hi;root.querySelector('[data-ymax]').textContent=top.toFixed(2);root.querySelector('[data-answer]').textContent='U = '+y.toFixed(5)+' kcal mol⁻¹. '+(mode.value==='bond'?'Fᵣ = '+(-2*529.581*(x-1.012)).toFixed(3)+' kcal mol⁻¹ Å⁻¹. ':mode.value==='angle'?(en?'Angular differences are converted to radians.':'角偏离先换成弧度再平方。'):(en?'The threefold cosine term repeats every 120°.':'三重周期余弦项每120°重复一次。'));}function set(){const a=models[mode.value];s.min=a.lo;s.max=a.hi;s.step=a.step;s.value=a.start;draw();}mode.addEventListener('change',set);s.addEventListener('input',draw);root.querySelector('[data-reset]').addEventListener('click',()=>{mode.value='bond';set();});set();});